"use client";

import { getSvgPath } from "figma-squircle";
import { AnimatePresence, MotionConfig, motion, useIsPresent, useReducedMotion } from "motion/react";
import { useId, useLayoutEffect, useRef, useState, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import { ledgerMotion, ledgerVariables } from "./ledger-tokens";
import "./ledger.css";

export { ledgerMotion, ledgerVariables } from "./ledger-tokens";

const ledgerDefaults = Object.fromEntries(Object.entries(ledgerVariables).map(([name, value]) => [name.replace("--ledger-", "--ledger-default-"), value]));

const cornerTargets = "[data-ledger-corner]";
const cornerOwners = new WeakMap<HTMLElement, symbol>();
const animatedStyleProperties = new Set(["transform", "transform-origin", "translate", "rotate", "scale", "opacity", "will-change", "--ledger-corner-mask"]);

export function ledgerCornerStyleKey(entries: readonly (readonly [string, string, string?])[]) {
  return entries.filter(([property]) => !animatedStyleProperties.has(property)).map(([property, value, priority]) => `${property}:${value}${priority ? `!${priority}` : ""}`).sort().join(";");
}

function useLedgerCorners(root: React.RefObject<HTMLDivElement | null>) {
  useLayoutEffect(() => {
    const scope = root.current;
    if (!scope) return;
    const owner = Symbol("Ledger corners");
    const observed = new Set<HTMLElement>();
    const geometry = new WeakMap<HTMLElement, string>();
    const styleKeys = new WeakMap<Element, string>();
    const parser = document.createElement("div").style;
    const styleKey = (style: CSSStyleDeclaration) => ledgerCornerStyleKey(Array.from({ length: style.length }, (_, index) => {
      const property = style.item(index);
      return [property, style.getPropertyValue(property), style.getPropertyPriority(property)] as const;
    }));
    const owns = (element: HTMLElement) => scope.contains(element) && element.closest("[data-ledger-theme]") === scope && element.matches(cornerTargets);
    const update = (element: HTMLElement) => {
      if (!observed.has(element) || !owns(element)) return;
      const width = element.offsetWidth;
      const height = element.offsetHeight;
      const style = getComputedStyle(element);
      const radius = Number.parseFloat(style.borderTopLeftRadius);
      const rawSmoothing = Number.parseFloat(style.getPropertyValue("--ledger-corner-smoothing") || style.getPropertyValue("--ledger-default-corner-smoothing"));
      const smoothing = Number.isFinite(rawSmoothing) ? Math.max(0, Math.min(1, rawSmoothing)) : 0.6;
      const key = `${width}:${height}:${radius}:${smoothing}`;
      if (geometry.get(element) === key) return;
      geometry.set(element, key);
      if (width < 2 || height < 2 || !Number.isFinite(radius) || radius <= 0) {
        element.style.removeProperty("--ledger-corner-mask");
        delete element.dataset.ledgerCorners;
        return;
      }
      const path = getSvgPath({ width, height, cornerRadius: Math.min(radius, width / 2, height / 2), cornerSmoothing: smoothing, preserveSmoothing: true });
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none"><path fill="black" d="${path}"/></svg>`;
      element.style.setProperty("--ledger-corner-mask", `url("data:image/svg+xml,${encodeURIComponent(svg)}")`);
      element.dataset.ledgerCorners = "true";
    };
    const resize = new ResizeObserver((entries) => entries.forEach(({ target }) => update(target as HTMLElement)));
    const release = (element: HTMLElement) => {
      if (!observed.delete(element)) return;
      resize.unobserve(element);
      geometry.delete(element);
      styleKeys.delete(element);
      if (cornerOwners.get(element) === owner) {
        cornerOwners.delete(element);
        element.style.removeProperty("--ledger-corner-mask");
        delete element.dataset.ledgerCorners;
      }
    };
    const observe = (element: Element) => {
      if (!(element instanceof HTMLElement) || !owns(element)) return;
      if (cornerOwners.get(element) !== owner) {
        cornerOwners.set(element, owner);
        geometry.delete(element);
      }
      if (!observed.has(element)) {
        observed.add(element);
        styleKeys.set(element, styleKey(element.style));
        resize.observe(element);
      }
      update(element);
    };
    const scanAdded = (node: Element) => {
      observe(node);
      node.querySelectorAll(cornerTargets).forEach(observe);
    };
    const refreshTree = (node: Element) => {
      for (const element of observed) {
        if (node === element || node.contains(element)) {
          if (owns(element)) update(element);
          else release(element);
        }
      }
    };
    scanAdded(scope);
    const mutations = new MutationObserver((records) => {
      const refresh = new Set<Element>();
      for (const record of records) {
        if (record.type === "childList") {
          for (const node of record.removedNodes) {
            if (!(node instanceof Element)) continue;
            for (const element of observed) {
              if ((node === element || node.contains(element)) && !owns(element)) release(element);
            }
          }
          for (const node of record.addedNodes) if (node instanceof Element) scanAdded(node);
          continue;
        }
        const target = record.target;
        if (!(target instanceof HTMLElement)) continue;
        if (record.attributeName === "style") {
          const next = styleKey(target.style);
          let previous = styleKeys.get(target);
          if (previous === undefined) {
            parser.cssText = record.oldValue ?? "";
            previous = styleKey(parser);
          }
          styleKeys.set(target, next);
          if (previous === next) continue;
        }
        if (record.attributeName === "data-ledger-corner" || record.attributeName === "data-ledger-theme") scanAdded(target);
        refresh.add(target);
      }
      for (const node of refresh) refreshTree(node);
    });
    mutations.observe(scope, { childList: true, subtree: true, attributes: true, attributeOldValue: true, attributeFilter: ["class", "style", "data-ledger-corner", "data-ledger-radius", "data-ledger-theme"] });
    return () => {
      mutations.disconnect();
      resize.disconnect();
      for (const element of observed) release(element);
    };
  }, [root]);
}

export function LedgerProvider({ children, className, style }: { children: ReactNode; className?: string; style?: CSSProperties }) {
  const root = useRef<HTMLDivElement>(null);
  useLedgerCorners(root);
  return <MotionConfig reducedMotion="user"><div ref={root} data-ledger-theme="" className={className} style={{ ...ledgerDefaults, ...style } as CSSProperties}>{children}</div></MotionConfig>;
}

export function LedgerSurface({ tone = "paper", radius = "panel", elevation = "none", className, ...props }: ComponentProps<"div"> & { tone?: "canvas" | "paper" | "ink" | "muted"; radius?: "shell" | "panel" | "card" | "control"; elevation?: "none" | "panel" | "floating" }) {
  return <div data-slot="card" data-ledger-corner="" data-ledger-tone={tone} data-ledger-radius={radius} data-ledger-elevation={elevation} className={["ledger-surface", className].filter(Boolean).join(" ")} {...props} />;
}

export function LedgerButton({ variant = "ghost", className, type = "button", ...props }: ComponentProps<"button"> & { variant?: "primary" | "ghost" }) {
  return <button data-slot="button" data-ledger-corner="" data-ledger-variant={variant} type={type} className={["ledger-button", className].filter(Boolean).join(" ")} {...props} />;
}

export function LedgerTable({ className, ...props }: ComponentProps<"table">) {
  return <div className="ledger-table-scroll" data-slot="ledger-table-scroll" tabIndex={0} role="region" aria-label={props["aria-label"] ? `${props["aria-label"]} table` : "Scrollable table"}><div className="ledger-table-mask" data-slot="table-container" data-ledger-corner=""><table data-slot="table" className={["ledger-table", className].filter(Boolean).join(" ")} {...props} /></div></div>;
}

function SearchIcon({ close = false }: { close?: boolean }) {
  return <svg aria-hidden="true" width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.3">{close ? <path d="m4 4 8 8M12 4l-8 8" /> : <><circle cx="6.8" cy="6.8" r="4.5" /><path d="m10.2 10.2 3.5 3.5" /></>}</svg>;
}

function SearchField({ value, onValueChange, close, label, placeholder }: { value: string; onValueChange: (value: string) => void; close: () => void; label: string; placeholder: string }) {
  const present = useIsPresent();
  const reduced = useReducedMotion();
  return <motion.div data-slot="ledger-search-field" data-ledger-corner="" className="ledger-search-field" inert={!present} aria-hidden={!present} initial={{ opacity: 0, x: reduced ? 0 : 5, scale: reduced ? 1 : 0.975 }} animate={{ opacity: 1, x: 0, scale: 1 }} exit={{ opacity: 0, x: reduced ? 0 : 5, scale: reduced ? 1 : 0.975, transition: reduced ? { duration: 0 } : ledgerMotion.exit }} transition={reduced ? { duration: 0 } : ledgerMotion.enter} onKeyDown={(event) => { if (event.key === "Escape") { event.preventDefault(); close(); } }}>
    <SearchIcon /><input autoFocus aria-label={label} placeholder={placeholder} value={value} onChange={(event) => onValueChange(event.target.value)} /><LedgerButton className="ledger-search-close" aria-label="Close search" onClick={close}><SearchIcon close /></LedgerButton>
  </motion.div>;
}

function SearchSummary({ children, restoreFocus, open, label }: { children: ReactNode; restoreFocus: boolean; open: () => void; label: string }) {
  const present = useIsPresent();
  const reduced = useReducedMotion();
  return <motion.div className="ledger-search-idle" inert={!present} aria-hidden={!present} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={reduced ? { duration: 0 } : ledgerMotion.summary}><span>{children}</span><LedgerButton autoFocus={restoreFocus} aria-label={label} aria-expanded={false} onClick={open}><SearchIcon /></LedgerButton></motion.div>;
}

export function LedgerSearch({ value, onValueChange, placeholder = "Search", label = "Search", summary }: { value: string; onValueChange: (value: string) => void; placeholder?: string; label?: string; summary?: ReactNode }) {
  const [open, setOpen] = useState(false);
  const [hasOpened, setHasOpened] = useState(false);
  const close = () => { setOpen(false); onValueChange(""); };
  return <div className="ledger-search" data-slot="ledger-search"><AnimatePresence initial={false} mode="wait">{open ? <SearchField key="field" value={value} onValueChange={onValueChange} close={close} label={label} placeholder={placeholder} /> : <SearchSummary key="summary" restoreFocus={hasOpened} label={label} open={() => { setHasOpened(true); setOpen(true); }}>{summary}</SearchSummary>}</AnimatePresence></div>;
}

function PresenceContent({ children, className }: { children: ReactNode; className?: string }) {
  const present = useIsPresent();
  const reduced = useReducedMotion();
  return <motion.div className={className} data-slot="ledger-presence" inert={!present} aria-hidden={!present} layout={!reduced} initial={{ opacity: 0, x: reduced ? 0 : 5, scale: reduced ? 1 : 0.975 }} animate={{ opacity: 1, x: 0, scale: 1 }} exit={{ opacity: 0, x: reduced ? 0 : 5, scale: reduced ? 1 : 0.975, transition: reduced ? { duration: 0 } : ledgerMotion.exit }} transition={{ ...(reduced ? { duration: 0 } : ledgerMotion.enter), layout: reduced ? { duration: 0 } : ledgerMotion.layout }}>{children}</motion.div>;
}

export function LedgerPresence({ show, children, className }: { show: boolean; children: ReactNode; className?: string }) {
  return <AnimatePresence initial={false}>{show && <PresenceContent key="content" className={className}>{children}</PresenceContent>}</AnimatePresence>;
}

export function LedgerRangeSelector({ value, options, onValueChange }: { value: string; options: readonly string[]; onValueChange: (value: string) => void }) {
  const id = useId();
  const reduced = useReducedMotion();
  return <div className="ledger-range" role="group" aria-label="Chart range">{Array.from(new Set(options)).map((option) => <button type="button" data-ledger-corner="" key={option} aria-pressed={option === value} onClick={() => onValueChange(option)}>{option === value && <motion.span className="ledger-range-selection" data-ledger-corner="" layoutId={`ledger-range-${id}`} transition={reduced ? { duration: 0 } : ledgerMotion.layout} />}<span>{option}</span></button>)}</div>;
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useMemo, useRef, useState, type CSSProperties } from "react";
import { ledgerMotion, ledgerVariables } from "./ledger-tokens";
import "./ledger.css";

export type LedgerDatum = { label: string; value: number };
export type LedgerChartProps = { data: readonly LedgerDatum[]; label: string; formatValue?: (value: number) => string; className?: string };

export const ledgerChartGeometry = {
  width: Number(ledgerVariables["--ledger-chart-width"]),
  height: Number(ledgerVariables["--ledger-chart-height"]),
  inset: Number(ledgerVariables["--ledger-chart-inset"]),
  samples: Number(ledgerVariables["--ledger-chart-samples"]),
};

export function ledgerChartIndex(progress: number, length: number) {
  if (length < 1) return -1;
  const clamped = Number.isNaN(progress) ? 0 : Math.max(0, Math.min(1, progress));
  return Math.round(clamped * (length - 1));
}

export function ledgerResample(values: readonly number[], count = ledgerChartGeometry.samples): number[] {
  if (!Number.isInteger(count) || count < 2) throw new RangeError("Sample count must be an integer of at least two.");
  if (values.length === 0) return [];
  if (values.some((value) => !Number.isFinite(value))) throw new RangeError("Chart values must be finite.");
  return Array.from({ length: count }, (_, index) => {
    const position = index / (count - 1) * (values.length - 1);
    const lower = Math.floor(position);
    const upper = Math.min(values.length - 1, lower + 1);
    const fraction = position - lower;
    return values[lower] * (1 - fraction) + values[upper] * fraction;
  });
}

export function ledgerChartPoint(values: readonly number[], index: number) {
  const { width, height, inset } = ledgerChartGeometry;
  if (values.length === 0) return { x: width / 2, y: height / 2 };
  const safeIndex = Math.max(0, Math.min(values.length - 1, Number.isFinite(index) ? Math.round(index) : 0));
  let min = Infinity;
  let max = -Infinity;
  for (const value of values) { min = Math.min(min, value); max = Math.max(max, value); }
  const scale = Math.max(Math.abs(min), Math.abs(max)) || 1;
  const span = max / scale - min / scale;
  const progress = span === 0 ? 0.5 : (values[safeIndex] / scale - min / scale) / span;
  return { x: values.length === 1 ? width / 2 : safeIndex / (values.length - 1) * width, y: height - inset - progress * (height - inset * 2) };
}

export function ledgerChartPaths(values: readonly number[]) {
  if (values.length === 0) return { line: "", area: "" };
  if (values.some((value) => !Number.isFinite(value))) throw new RangeError("Chart values must be finite.");
  let min = Infinity;
  let max = -Infinity;
  for (const value of values) { min = Math.min(min, value); max = Math.max(max, value); }
  const { width, height, inset } = ledgerChartGeometry;
  const scale = Math.max(Math.abs(min), Math.abs(max)) || 1;
  const span = max / scale - min / scale;
  const ordinates = values.map((value) => height - inset - (span === 0 ? 0.5 : (value / scale - min / scale) / span) * (height - inset * 2));
  const sampled = ledgerResample(ordinates);
  const line = sampled.map((y, index) => `${index === 0 ? "M" : "L"}${(index / (sampled.length - 1) * width).toFixed(3)},${y.toFixed(3)}`).join(" ");
  return { line, area: `${line} L${ledgerChartGeometry.width},${ledgerChartGeometry.height} L0,${ledgerChartGeometry.height} Z` };
}

const defaultFormat = (value: number) => value.toLocaleString();

export function LedgerChart({ data, label, formatValue = defaultFormat, className }: LedgerChartProps) {
  const series = useMemo(() => data.filter((datum) => Number.isFinite(datum.value)), [data]);
  const values = useMemo(() => series.map((datum) => datum.value), [series]);
  const paths = useMemo(() => ledgerChartPaths(values), [values]);
  const [hovered, setHovered] = useState<{ series: readonly LedgerDatum[]; index: number } | null>(null);
  const active = hovered?.series === series ? hovered.index : null;
  const index = active ?? series.length - 1;
  const point = ledgerChartPoint(values, index);
  const svg = useRef<SVGSVGElement>(null);
  const gradient = useId();
  const instructions = useId();
  const tooltip = useId();
  const reduced = useReducedMotion();
  const { width, height, inset } = ledgerChartGeometry;
  const transition = reduced ? { duration: 0 } : ledgerMotion.chart;
  const move = (clientX: number) => {
    const bounds = svg.current?.getBoundingClientRect();
    if (!bounds || bounds.width <= 0 || series.length === 0) return;
    setHovered({ series, index: ledgerChartIndex((clientX - bounds.left) / bounds.width, series.length) });
  };
  const select = (next: number) => setHovered({ series, index: Math.max(0, Math.min(series.length - 1, next)) });
  const labels = [...new Set([0, Math.floor((series.length - 1) / 2), series.length - 1])].filter((position) => position >= 0);

  return <div className={["ledger-chart", className].filter(Boolean).join(" ")} data-slot="ledger-chart">
    <div className="ledger-chart-readout"><span>{label}</span><span>{series[index] ? formatValue(series[index].value) : ""}</span></div>
    {series.length === 0 ? <div className="ledger-chart-empty" role="status">No data</div> : <>
      <div className="ledger-chart-plot">
        <svg ref={svg} viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" role="img" tabIndex={0} aria-label={label} aria-describedby={active === null ? instructions : `${instructions} ${tooltip}`} onPointerMove={(event) => move(event.clientX)} onPointerLeave={() => setHovered(null)} onPointerCancel={() => setHovered(null)} onBlur={() => setHovered(null)} onPointerDown={(event) => { event.currentTarget.setPointerCapture(event.pointerId); move(event.clientX); }} onKeyDown={(event) => {
          if (event.key === "Escape") { event.preventDefault(); setHovered(null); }
          else if (event.key === "ArrowLeft") { event.preventDefault(); select((active ?? series.length - 1) - 1); }
          else if (event.key === "ArrowRight") { event.preventDefault(); select((active ?? series.length - 1) + 1); }
          else if (event.key === "Home") { event.preventDefault(); select(0); }
          else if (event.key === "End") { event.preventDefault(); select(series.length - 1); }
        }}>
          <defs><linearGradient id={gradient} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--ledger-chart-fill, var(--ledger-default-chart-fill))" stopOpacity="0.1" /><stop offset="100%" stopColor="var(--ledger-chart-fill, var(--ledger-default-chart-fill))" stopOpacity="0" /></linearGradient></defs>
          <path d={`M0 ${height - inset} H${width}`} fill="none" stroke="var(--ledger-chart-baseline, var(--ledger-default-chart-baseline))" strokeDasharray="2 5" />
          <motion.path data-slot="ledger-chart-area" initial={false} animate={{ d: paths.area }} transition={transition} fill={`url(#${gradient})`} />
          <motion.path data-slot="ledger-chart-line" initial={false} animate={{ d: paths.line }} transition={transition} fill="none" stroke="var(--ledger-chart-line, var(--ledger-default-chart-line))" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
          {active !== null && <path d={`M${point.x} 0 V${height}`} fill="none" stroke="var(--ledger-chart-rule, var(--ledger-default-chart-rule))" strokeDasharray="2 4" />}
          <motion.circle initial={false} animate={{ cx: point.x, cy: point.y, r: active === null ? 2 : 3 }} transition={active === null ? transition : { duration: 0 }} fill="var(--ledger-accent, var(--ledger-default-accent))" />
        </svg>
        <AnimatePresence>{active !== null && <div key="tooltip" className="ledger-chart-tooltip-anchor" style={{ left: `clamp(0px, calc(${point.x / width * 100}% - var(--ledger-chart-tooltip-width, var(--ledger-default-chart-tooltip-width)) / 2), max(0px, calc(100% - var(--ledger-chart-tooltip-width, var(--ledger-default-chart-tooltip-width)))))` } as CSSProperties}>
          <motion.div id={tooltip} data-ledger-corner="" className="ledger-chart-tooltip" role="status" initial={reduced ? false : { opacity: 0, scale: 0.96, y: 4 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: reduced ? 1 : 0.96, y: reduced ? 0 : 4 }} transition={reduced ? { duration: 0 } : ledgerMotion.tooltip}><span>{series[index].label}</span><strong>{formatValue(series[index].value)}</strong></motion.div>
        </div>}</AnimatePresence>
        <span id={instructions} className="ledger-visually-hidden">Use left and right arrow keys to inspect values. Press Home or End for the first or last value. Press Escape to clear the selection.</span>
      </div>
      <div className="ledger-chart-labels">{labels.map((position) => <span key={position}>{series[position].label}</span>)}</div>
    </>}
  </div>;
}

[data-ledger-theme] {
  font-family: var(--ledger-font-body, var(--ledger-default-font-body));
  color: var(--ledger-foreground, var(--ledger-default-foreground));
  background: transparent;
  color-scheme: light;
  -webkit-font-smoothing: antialiased;
}
[data-ledger-theme] *, [data-ledger-theme] *::before, [data-ledger-theme] *::after { box-sizing: border-box; }
[data-ledger-theme] :where(button, input) { font-family: inherit; }
[data-ledger-theme] :is(h1, h2, h3, h4, h5, h6) { font-family: var(--ledger-font-heading, var(--ledger-default-font-heading)); }
[data-ledger-theme] :where(button, input, a, [tabindex]):focus-visible { outline: 2px solid var(--ledger-accent, var(--ledger-default-accent)); outline-offset: 4px; }
[data-ledger-theme] :where(button) { cursor: pointer; }
[data-ledger-theme] :where(button:disabled) { cursor: default; opacity: 0.4; }
[data-ledger-theme] [data-ledger-corners] { position: relative; isolation: isolate; background: transparent; }
[data-ledger-theme] [data-ledger-corners]::before {
  content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
  background: var(--ledger-fill, var(--ledger-paper, var(--ledger-default-paper)));
  mask: var(--ledger-corner-mask) center / 100% 100% no-repeat;
  -webkit-mask: var(--ledger-corner-mask) center / 100% 100% no-repeat;
  transition: background-color var(--ledger-motion-hover, var(--ledger-default-motion-hover)) ease;
}
[data-ledger-theme] .ledger-surface { border-radius: var(--ledger-radius-card, var(--ledger-default-radius-card)); --ledger-fill: var(--ledger-paper, var(--ledger-default-paper)); }
[data-ledger-theme] .ledger-button { border-radius: var(--ledger-radius-control, var(--ledger-default-radius-control)); --ledger-fill: var(--ledger-paper, var(--ledger-default-paper)); }
[data-ledger-theme] .ledger-surface { container-type: inline-size; min-width: 0; padding: var(--ledger-space-panel, var(--ledger-default-space-panel)); background: var(--ledger-fill); border: 0; }
[data-ledger-theme] .ledger-surface[data-ledger-corners] { background: transparent; }
[data-ledger-theme] [data-ledger-tone="canvas"] { --ledger-fill: var(--ledger-canvas, var(--ledger-default-canvas)); color: var(--ledger-foreground, var(--ledger-default-foreground)); }
[data-ledger-theme] [data-ledger-tone="paper"] { --ledger-fill: var(--ledger-paper, var(--ledger-default-paper)); color: var(--ledger-foreground, var(--ledger-default-foreground)); }
[data-ledger-theme] [data-ledger-tone="ink"] { --ledger-fill: var(--ledger-ink, var(--ledger-default-ink)); color: var(--ledger-inverse, var(--ledger-default-inverse)); }
[data-ledger-theme] [data-ledger-tone="muted"] { --ledger-fill: var(--ledger-muted, var(--ledger-default-muted)); color: var(--ledger-inverse, var(--ledger-default-inverse)); }
[data-ledger-theme] [data-ledger-radius="shell"] { border-radius: var(--ledger-radius-shell, var(--ledger-default-radius-shell)); padding: var(--ledger-space-shell, var(--ledger-default-space-shell)); }
[data-ledger-theme] [data-ledger-radius="panel"] { border-radius: var(--ledger-radius-panel, var(--ledger-default-radius-panel)); }
[data-ledger-theme] [data-ledger-radius="card"] { border-radius: var(--ledger-radius-card, var(--ledger-default-radius-card)); }
[data-ledger-theme] [data-ledger-radius="control"] { border-radius: var(--ledger-radius-control, var(--ledger-default-radius-control)); }
